}
console.log('R1/R2: 20,001 subtotals per code passed integer rounding and floor checks');
for(const c of ['', 'BOGUS', 'SAVE11', ' FLAT5', 'SAVE10 ']) for(const n of [0,3,98765]) assert.throws(()=>d(n,c),Error);
assert.equal(d(10000),10000);
console.log('R3: 15 unknown-code calls throw; visible no-code call preserved');
let seed=79;
for(let i=0;i<1000;i++) {
 seed=(seed*1664525+1013904223)>>>0;
